import { ScrollVideoSequence } from '../components/scroll-video-sequence/scroll-video-sequence.js';

/**
 * Sets up the project scroll-video section (#projectVideo).
 *
 * The frame sequence is videoProjetos1 followed immediately by
 * videoProjetos2 (see assets/videos/manifest-projeto.json, generated by
 * scripts/generate-frame-manifest.mjs) — one continuous scroll-driven clip.
 *
 * Once the sequence settles on its very last frame, the project gallery
 * (built in project-gallery.js, passed in here as `galleryElement`) fades in
 * on top of it.
 */
export function initProjectVideo(galleryElement) {
  const GALLERY_FADE_START = 0.96; // only once the sequence has essentially finished

  new ScrollVideoSequence({
    section: '#projectVideo',
    manifestUrl: 'assets/videos/manifest-projeto.json',
    scrub: 0.15,
    onProgress: (progress) => {
      const opacity = Math.min(1, Math.max(0, (progress - GALLERY_FADE_START) / (1 - GALLERY_FADE_START)));
      galleryElement.style.opacity = opacity;
      // Only clickable (arrows, dots, links) once fully visible — otherwise
      // it would swallow clicks meant for the video while still fading in.
      galleryElement.style.pointerEvents = opacity >= 0.99 ? 'auto' : 'none';
    },
  });
}
